let _obadmBank = null;
function _oralBankClone(){ var out={}; [1,2,3,4,5].forEach(function(n){ out[n]=(getSieleOralBank()[n]||[]).map(function(q){return JSON.parse(JSON.stringify(q));}); }); return out; }
function renderOralBankAdmin(keep){
  if(!keep) _obadmBank = _oralBankClone();
  var tareaNames = {1:'Tarea 1 · 短答',2:'Tarea 2 · 看图描述',3:'Tarea 3 · 情景对话',4:'Tarea 4 · 话题表达',5:'Tarea 5 · 议论文'};
  var h = '<div style="padding:6px 0"><h2>🔧 管理员编辑口语真题题库</h2><div class="sub" style="margin-bottom:10px">Tarea 1-5 全部题目，每题可编辑题目描述/内容/范例答案/关键词，支持增删改。保存后覆盖到所有用户。</div>';
  [1,2,3,4,5].forEach(function(n){
    var list = _obadmBank[n]||[];
    h += '<div class="card" style="margin:10px 0">';
    h += '<h3 style="margin-bottom:6px">'+esc(tareaNames[n])+' <span class="sub" style="font-size:12px">'+list.length+' 题</span></h3>';
    list.forEach(function(q, qi){
      h += '<div style="border:1px dashed var(--line);padding:8px;margin:6px 0;border-radius:6px;background:#fafafa">';
      h += '<div style="display:flex;justify-content:space-between;align-items:center;margin-bottom:4px"><span style="font-size:11px;color:var(--soft)">题 '+(qi+1)+'</span><button class="btn xs dgr" onclick="delOralBankQ('+n+','+qi+')">✕ 删除</button></div>';
      if(q.title) h += '<div style="margin:3px 0;font-size:12px"><b>标题：</b><input id="obadm_title_'+n+'_'+qi+'" value="'+esc(q.title)+'" style="width:100%"></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>题目描述：</b><textarea id="obadm_q_'+n+'_'+qi+'" rows="2" style="width:100%;font-size:12px">'+esc(q.q||'')+'</textarea></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>范例答案：</b><textarea id="obadm_model_'+n+'_'+qi+'" rows="4" style="width:100%;font-size:12px;font-family:var(--serif)">'+esc(q.model||'')+'</textarea></div>';
      h += '<div style="margin:3px 0;font-size:12px"><b>关键词：</b><input id="obadm_keys_'+n+'_'+qi+'" value="'+esc((q.keys||[]).join(', '))+'" style="width:100%"><span class="sub" style="font-size:10px">逗号分隔</span></div>';
      h += '<div style="display:flex;gap:8px;margin:3px 0;font-size:12px"><div><b>时长(秒)：</b><input id="obadm_sec_'+n+'_'+qi+'" value="'+esc(String(q.sec||''))+'" style="width:60px"></div></div>';
      h += '</div>';
    });
    h += '<button class="btn sm" onclick="addOralBankQ('+n+')">➕ 加题</button>';
    h += '</div>';
  });
  h += '<div style="display:flex;gap:8px;margin:12px 0"><button class="btn pr" onclick="saveOralBankAdmin()">💾 保存并同步给所有用户</button><button class="btn ol" onclick="renderMain()">❌ 取消</button></div></div>';
  var m = document.getElementById('main');
  if(m) m.innerHTML = h;
  window.scrollTo(0,0);
}
function addOralBankQ(n){
  if(!_obadmBank) return;
  _obadmBank[n] = _obadmBank[n]||[];
  _obadmBank[n].push({id:'t'+n+'_new_'+Date.now().toString(36),sec:10,q:'',keys:[],model:''});
  renderOralBankAdmin(true);
}
function delOralBankQ(n, qi){
  if(!_obadmBank||!_obadmBank[n]) return;
  if(!confirm('确定删除 Tarea '+n+' 第 '+(qi+1)+' 题？')) return;
  _obadmBank[n].splice(qi,1);
  renderOralBankAdmin(true);
}
function saveOralBankAdmin(){
  if(!_obadmBank) return;
  var bank = {};
  [1,2,3,4,5].forEach(function(n){
    var list = _obadmBank[n]||[];
    var out = [];
    for(var qi=0; qi<list.length; qi++){
      var q = list[qi];
      var o = {id:q.id||('t'+n+'_'+qi), sec:Number((document.getElementById('obadm_sec_'+n+'_'+qi)||{}).value||q.sec||10)};
      var titleEl = document.getElementById('obadm_title_'+n+'_'+qi);
      if(titleEl) o.title = titleEl.value;
      o.q = (document.getElementById('obadm_q_'+n+'_'+qi)||{}).value||'';
      o.model = (document.getElementById('obadm_model_'+n+'_'+qi)||{}).value||'';
      var keysVal = (document.getElementById('obadm_keys_'+n+'_'+qi)||{}).value||'';
      o.keys = keysVal.split(',').map(function(k){return k.trim();}).filter(Boolean);
      if(q.topic) o.topic = q.topic;
      if(q.formal!==undefined) o.formal = q.formal;
      if(q.photo!==undefined) o.photo = q.photo;
      out.push(o);
    }
    bank[n] = out;
  });
  window._deleSyncContentEdits('oralbank', {bank: bank});
  window._contentEdits.oralbank = {bank: bank};
  toast('✅ 已保存并同步给所有用户','ok');
  renderMain();
}

